from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="140" viewBox="0 0 680 140" role="img">\n<title>Code snippet</title><desc>random code</desc>\n<rect width="680" height="140" rx="16" fill="#0d1117"/>\n<text x="20" y="28" fill="#e6edf3" font-family="monospace" font-size="12">CODE SNIPPET — random from your repos · plugin_code</text>\n<g transform="translate(20,40)">\n  <rect width="640" height="70" rx="8" fill="#161b22" stroke="#30363d"/>\n  <text x="14" y="22" fill="#7d8590" font-family="monospace" font-size="9">def hello():</text>\n  <text x="14" y="36" fill="#e6edf3" font-family="monospace" font-size="10">    print("Hello, gitEdit!")</text>\n  <text x="14" y="54" fill="#7d8590" font-family="monospace" font-size="8">from atlas/samples/orbit-stack.py — lowlighter/metrics plugin_code</text>\n</g>\n</svg>\n'
